    } else {
        if (s[len - 1] != '_') {
            if (getDigit(s, len - 1) != end2) return 0;
        }
    }
    int totalWays = 1;
    for (int i = 0; i < len - 2; i++) {
        if (i == 0) {
            if (s[i] == 'X' && X_value == 0) return 0;
            if (getDigit(s, i) == 0) return 0;
        }
        if (s[i] == '_') {
            totalWays *= (i == 0) ? 9 : 10;
        }
        if (s[i] == 'X') {
