            else {
                X_value = 10;
                totalWays *= (i == 0) ? 9 : 10;
            }
        }
    }
    return totalWays;
}

int getDigit(const std::string& s, int pos) {
    if (s[pos] == '_' || s[pos] == 'X') return -1;
    return s[pos] - '0';
